from fractions import Fraction
from math import isqrt
import json

c = Fraction(20, -24) - (Fraction(2) + Fraction(-3))
original = {
    4: Fraction(1, 16),
    3: -c,
    2: Fraction(1, 8),
    1: Fraction(0),
    0: Fraction(1),
}
derivative = {power - 1: power * coefficient
              for power, coefficient in original.items() if power > 0}

a, b, d = derivative[3], derivative[2], derivative[1]
discriminant = b * b - 4 * a * d

if derivative[0] != 0 or a == 0 or discriminant < 0:
    print("UNSUPPORTED")
else:
    numerator_root = isqrt(discriminant.numerator)
    denominator_root = isqrt(discriminant.denominator)
    if (numerator_root**2 != discriminant.numerator or
            denominator_root**2 != discriminant.denominator):
        print("UNSUPPORTED")
    else:
        sqrt_discriminant = Fraction(numerator_root, denominator_root)
        roots = [
            (-b - sqrt_discriminant) / (2 * a),
            (-b + sqrt_discriminant) / (2 * a),
        ]

        def factor(root):
            if root == 0:
                return "s"
            sign = "-" if root > 0 else "+"
            return f"(s {sign} {abs(root)})"

        factors = ["s"]
        if roots[0] == roots[1]:
            factors.append(f"{factor(roots[0])}**2")
        else:
            factors.extend(factor(root) for root in roots)

        # Independently verify the expanded factorization.
        verified = (
            -a * (roots[0] + roots[1]) == b
            and a * roots[0] * roots[1] == d
        )
        if not verified:
            print("UNSUPPORTED")
        else:
            answer = f"({a})*" + "*".join(factors)
            print(json.dumps({
                "final_answer": answer,
                "evidence": {
                    "c": str(c),
                    "derivative_coefficients": {
                        str(power): str(derivative[power])
                        for power in sorted(derivative, reverse=True)
                    },
                    "quadratic_discriminant": str(discriminant),
                    "remaining_roots": [str(root) for root in roots],
                    "expansion_verified": verified
                }
            }, separators=(",", ":")))
